import{_ as e}from"./chunks/gnss-topic-echo.C1_-nlwO.js";import{_ as d,o as a,c as o,a5 as r}from"./chunks/framework.D47SInms.js";const u=JSON.parse('{"title":"GNSS · RTK (위성 측위)","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/interface/gnss.md","filePath":"ko/manual/interface/gnss.md","lastUpdated":1791600043000}'),s={name:"ko/manual/interface/gnss.md"};function n(i,t,l,c,h,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="gnss-·-rtk-위성-측위" tabindex="-1">GNSS · RTK (위성 측위) <a class="header-anchor" href="#gnss-·-rtk-위성-측위" aria-label="Permalink to &quot;GNSS · RTK (위성 측위)&quot;">​</a></h1><p>로봇에 GNSS 수신기를 연결하면 위성 측위 데이터를 <strong>NMEA 문장 그대로</strong> 받아 쓸 수 있습니다. 로봇의 <code>GPS</code> 프로그램이 수신기에서 문장을 읽어 ROS 2 토픽으로 그대로 흘려보냅니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>GNSS 는 <strong><code>GPS</code> 프로그램이 포함된 로봇 소프트웨어</strong>와 GNSS 수신기가 있어야 동작합니다. 수신기·LTE/GPS 모듈은 <a href="/RBQ/nightly/ko/manual/product-descriptions/accessories#wifi-lte-gps-module">액세서리</a>를 참고하세요.</p></div></div><h2 id="topic" tabindex="-1">토픽 <a class="header-anchor" href="#topic" aria-label="Permalink to &quot;토픽 {#topic}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>토픽</td><td><code>/rbq/gps/nmea</code></td></tr><tr><td>타입</td><td><a href="https://docs.ros.org/en/noetic/api/nmea_msgs/html/msg/Sentence.html" target="_blank" rel="noreferrer"><code>nmea_msgs/Sentence</code></a></td></tr><tr><td>방향</td><td>Pub (로봇 → 클라이언트)</td></tr></tbody></table><p>메시지는 두 필드뿐입니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>내용</th></tr></thead><tbody><tr><td><code>header.stamp</code></td><td>로봇이 그 문장을 <strong>읽은 시각</strong> (문장 안의 UTC 가 아닙니다)</td></tr><tr><td><code>header.frame_id</code></td><td><code>gps</code> — 수신기(안테나) 기준 좌표계</td></tr><tr><td><code>sentence</code></td><td>NMEA 0183 문장 원문 한 줄 (<code>$</code> 로 시작, 체크섬 포함)</td></tr></tbody></table><p>문장은 <strong>가공하지 않습니다.</strong> 파싱은 받는 쪽에서 하며, NMEA 는 표준 형식이라 대부분의 언어에 파서가 있습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/gps/nmea</span></span></code></pre></div><figure style="text-align:center;margin:1rem 0;"><img src="'+e+'" alt="ros2 topic echo /rbq/gps/nmea 출력 — GNRMC · GNGGA · GNGST 문장" style="display:block;margin:0 auto;max-width:100%;height:auto;border-radius:6px;"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 실제 수신 출력 — 한 주기에 세 문장이 순서대로 올라옵니다 ]</figcaption></figure><h2 id="sentences" tabindex="-1">나오는 문장 세 가지 <a class="header-anchor" href="#sentences" aria-label="Permalink to &quot;나오는 문장 세 가지 {#sentences}&quot;">​</a></h2><p>수신기가 내보내는 문장 중 아래 세 종류만 골라 발행합니다. 나머지는 버립니다. 접두어 <code>GN</code> 은 여러 위성군(GPS·GLONASS·Galileo·BeiDou)을 함께 쓴다는 뜻입니다.</p><h3 id="gnrmc" tabindex="-1"><code>$GNRMC</code> — 위치 · 속도 · 시각 <a class="header-anchor" href="#gnrmc" aria-label="Permalink to &quot;`$GNRMC` — 위치 · 속도 · 시각 {#gnrmc}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$GNRMC,&lt;UTC 시각&gt;,&lt;유효&gt;,&lt;위도&gt;,&lt;N/S&gt;,&lt;경도&gt;,&lt;E/W&gt;,&lt;속도&gt;,&lt;방위&gt;,&lt;UTC 날짜&gt;,&lt;자기편차&gt;,&lt;E/W&gt;,&lt;모드&gt;,&lt;항법상태&gt;*&lt;체크섬&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>필드</th><th>내용</th></tr></thead><tbody><tr><td>UTC 시각 · 날짜</td><td>측정 시각</td></tr><tr><td>유효</td><td>데이터 유효 여부 (<code>A</code> 유효 / <code>V</code> 무효)</td></tr><tr><td>위도 · 경도</td><td>위치</td></tr><tr><td>속도</td><td>지면 속도 (knots)</td></tr><tr><td>방위</td><td>진행 방향 (진북 기준)</td></tr><tr><td>자기편차</td><td>진북과 자북의 차이</td></tr><tr><td>모드 · 항법상태</td><td>위치결정 방식과 항법 상태</td></tr></tbody></table><h3 id="gngga" tabindex="-1"><code>$GNGGA</code> — 측위 품질 · 고도 <a class="header-anchor" href="#gngga" aria-label="Permalink to &quot;`$GNGGA` — 측위 품질 · 고도 {#gngga}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$GNGGA,&lt;UTC 시각&gt;,&lt;위도&gt;,&lt;N/S&gt;,&lt;경도&gt;,&lt;E/W&gt;,&lt;측위품질&gt;,&lt;위성수&gt;,&lt;HDOP&gt;,&lt;고도&gt;,M,&lt;지오이드 분리&gt;,M,&lt;보정 경과시간&gt;,&lt;기준국 ID&gt;*&lt;체크섬&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>필드</th><th>내용</th></tr></thead><tbody><tr><td>측위품질</td><td><strong>RTK 상태를 여기서 확인합니다</strong> — 아래 표 참고</td></tr><tr><td>위성수</td><td>측위에 사용한 위성 개수</td></tr><tr><td>HDOP</td><td>수평 정밀도 저하율 — 낮을수록 좋습니다</td></tr><tr><td>고도</td><td>평균해수면 기준</td></tr><tr><td>지오이드 분리</td><td>타원체와 지오이드의 차이</td></tr><tr><td>보정 경과시간 · 기준국 ID</td><td>보정정보(RTCM)를 마지막으로 받은 뒤 지난 시간과 그 기준국</td></tr></tbody></table><p>측위품질 값은 NMEA 0183 표준입니다.</p><table tabindex="0"><thead><tr><th>값</th><th>뜻</th></tr></thead><tbody><tr><td><code>0</code></td><td>측위 없음</td></tr><tr><td><code>1</code></td><td>단독 측위 (GPS fix)</td></tr><tr><td><code>2</code></td><td>DGPS — 보정정보 적용</td></tr><tr><td><code>4</code></td><td><strong>RTK Fixed</strong> — 정수 모호성 해결, 가장 정확</td></tr><tr><td><code>5</code></td><td><strong>RTK Float</strong> — 모호성 미해결</td></tr></tbody></table><h3 id="gngst" tabindex="-1"><code>$GNGST</code> — 위치 오차 추정 <a class="header-anchor" href="#gngst" aria-label="Permalink to &quot;`$GNGST` — 위치 오차 추정 {#gngst}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$GNGST,&lt;UTC 시각&gt;,&lt;RMS&gt;,&lt;장축 σ&gt;,&lt;단축 σ&gt;,&lt;타원 방향&gt;,&lt;위도 σ&gt;,&lt;경도 σ&gt;,&lt;고도 σ&gt;*&lt;체크섬&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>필드</th><th>내용</th></tr></thead><tbody><tr><td>RMS</td><td>거리측정 잔차의 RMS</td></tr><tr><td>장축 · 단축 σ · 타원 방향</td><td>위치 오차 타원의 표준편차와 방향</td></tr><tr><td>위도 · 경도 · 고도 σ</td><td>축별 위치 오차 표준편차 (m)</td></tr></tbody></table><p><strong>RTK 로 얼마나 정확해졌는지는 이 문장으로 판단합니다.</strong> 위도·경도 σ 가 센티미터 수준으로 떨어지면 RTK 가 물린 것입니다.</p><h2 id="verify" tabindex="-1">잘 동작하는지 확인 <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;잘 동작하는지 확인 {#verify}&quot;">​</a></h2><ol><li><strong>토픽이 흐르는지</strong> — <code>ros2 topic echo /rbq/gps/nmea</code> 에 문장이 올라오는지 봅니다.</li><li><strong>측위가 잡혔는지</strong> — <code>$GNGGA</code> 의 측위품질이 <code>0</code> 이면 아직 위성을 못 잡은 것입니다. 하늘이 열린 곳으로 옮겨 잠시 기다리세요.</li><li><strong>RTK 가 물렸는지</strong> — 측위품질이 <code>4</code>(Fixed) 또는 <code>5</code>(Float) 인지, 그리고 <code>$GNGST</code> 의 위도·경도 σ 가 충분히 작은지 확인합니다.</li></ol><p>로그는 <strong><a href="/RBQ/nightly/ko/manual/gui/logs.html#real-time">로그 → Real Time</a></strong> 에서 <code>GPS</code> 프로세스만 남겨 보면 접속·해제 메시지를 바로 확인할 수 있습니다.</p><h2 id="troubleshooting" tabindex="-1">잘 안 될 때 <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;잘 안 될 때 {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>증상</th><th>원인과 조치</th></tr></thead><tbody><tr><td>토픽에 아무것도 안 옵니다</td><td>수신기가 로봇에 물려 있고 전원이 들어와 있는지 확인하세요. 로봇에서 수신기 주소로 닿는지도 함께 봅니다</td></tr><tr><td>접속은 되는데 문장이 없습니다</td><td>위 세 종류(<code>GNRMC</code>·<code>GNGGA</code>·<code>GNGST</code>) 외에는 버립니다. 수신기 설정에서 해당 문장 출력을 켜세요</td></tr><tr><td>측위품질이 <code>1</code> 에서 안 올라갑니다</td><td>보정정보(RTCM)가 안 들어오는 상태입니다. <code>$GNGGA</code> 의 보정 경과시간과 기준국 ID 를 확인하세요</td></tr><tr><td>실내에서 측위가 안 잡힙니다</td><td>GNSS 는 하늘이 보여야 합니다. 실내·고층 사이에서는 측위가 안 되거나 오차가 큽니다</td></tr></tbody></table><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>수신기 모델과 <code>ros2 topic echo /rbq/gps/nmea</code> 출력 몇 줄을 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a></strong></p>',32)])])}const m=d(s,[["render",n]]);export{u as __pageData,m as default};
